<?php require_once __DIR__.'/../includes/permissions.php';require_permission('records.view');$u=current_user();$pdo=db();if($_SERVER['REQUEST_METHOD']==='GET'){ $sql='SELECT hr.id,r.patient_id,s.name service_name,hr.record_type,hr.record_date,hr.assigned_staff_id,hr.status FROM health_records hr JOIN residents r ON r.id=hr.resident_id JOIN services s ON s.id=hr.service_id WHERE hr.status="Active"';$p=[];if($u['role_name']!=='System Administrator'){$sql.=' AND hr.assigned_staff_id=?';$p[]=$u['id'];}$sql.=' ORDER BY hr.record_date DESC LIMIT 300';$q=$pdo->prepare($sql);$q->execute($p);json_response(['success'=>true,'data'=>$q->fetchAll()]);}if($_SERVER['REQUEST_METHOD']==='POST'){require_permission('records.create');$d=json_decode(file_get_contents('php://input'),true)?:$_POST;$assigned=$u['role_name']==='System Administrator'?($d['assigned_staff_id']??null):$u['id'];$q=$pdo->prepare('INSERT INTO health_records(resident_id,service_id,record_type,record_date,assigned_staff_id,diagnosis_summary,notes,created_by) VALUES(?,?,?,?,?,?,?,?)');$q->execute([(int)$d['resident_id'],(int)$d['service_id'],$d['record_type'],$d['record_date'],$assigned,$d['diagnosis_summary']??null,$d['notes']??null,$u['id']]);json_response(['success'=>true,'id'=>(int)$pdo->lastInsertId()],201);}json_response(['success'=>false,'message'=>'Unsupported request'],405);
